comp:
// (built-in) uniform sampler2D sampler_pw_noise_lq;

float k1, k2, mask1, mask2, mask3, rad1, rad2, rad3;
vec2 rs, rss, rss0, rs0, uv2, uv3,uv4, rsk, uvo;
vec2 dz1, dz2, dz3, Kugel1, Kugel2, Kugel3,tmp;
vec3 noise, ret1, ret2, cathed, sky, fire;






shader_body
{
uvo = uv*aspect.xy;
uv = (mat2(_qa) * uv*aspect.xy);
uv = uv + -.0- .2*vec2(q5,q6);
vec2 uv1 = vec2((uv-.5 ));//*aspect.xy;

//Kugel1
rsk = (uv1 + vec2 (q9,q10)) ;
dz1 = vec2(normalize(rsk));
rad1 = q11*length (rsk) ;
uv4 =  tan(rad1)*dz1;
mask1 = clamp(8.0-8.0*rad1, 0.0, 1.0);
Kugel1 = uv4*mask1*8.0/q11;
uv1 += Kugel1*.1;

//Kugel2
rsk = vec2((sin(q27*atan(uv1.x,uv1.y)/2.0)));
dz2 = normalize(rsk);
rad2 = 1.0*length (rsk) ;
uv4 =  tan(rad2)*dz2;
mask2 = clamp(8.0-8.0*rad2, 0.0, 1.0);
Kugel2 = uv4*mask2;

//Kugel3
float argu = length(uv1+q5*uv1.y);
rsk = vec2((sin(.1*(q27-8.0)/ argu)));
//rsk = (sin(.5*q27*atan(uv1.x,uv1.y))) ;
dz3 = normalize(rsk);
rad3 = 1.0*length (rsk) ;
uv4 =  tan(-rad3)*dz3;
mask3 = clamp(8.0-8.0*rad3, 0.0, 1.0);
Kugel3 = uv4*mask3;

vec2 dz = (Kugel1 + q12*Kugel2*length(uv1) + q13*Kugel3*argu);
//******************** STARS
rss0.x = atan(uv1.x, uv1.y)/3.1416;
rss0.y = .01/(length (uv1));

rss = vec2 (rss0.x,rss0.y+time/2.0)+dz;
rss = (mat2(.7,.7,-.7,.7) * rss);
float noise = (texture(sampler_pw_noise_lq,rss/32.0).xyz-.8 >= 0.0);
tmp = abs(fract(rss*8.0)-.5);

//*************************
uv1 -= dz*.5;
float z = .2/(length(uv1)+q21);
uv2.y = z + q8;
uv2.x = rss0.x +q7;
uv3 =fract(uv2);
cathed =  texture (sampler_main,uv3+.4*dz).xyz*12.0;

float _mod = (q22+1.0)/6.0;

//Deckenbeleuchtung:
fire = clamp(.05*q22/length (uv1)*
 (lum(texture (sampler_main,uv3+.0).xyz)), 0.0, 1.0) ;

//Tasaechl. Feuer; Problem: uv1 passt nicht zu uv3
fire += clamp(.02*q22/length (uv1)*
 (lum(texture (sampler_main,uv1+.5).xyz)), 0.0, 1.0)/length(uv1);

k1 = lum(fire);
fire = k1*vec3(1.0,k1*.8,k1*k1/3.0)  ;

uvo+=dz;
sky = clamp(.02/length(uvo-.3), 0.0, 1.0) * 1.0;

vec3 dots = vec3(clamp(.04/length(tmp), 0.0, 1.0) *noise);
dots *= clamp(.2/abs(rss0.y), 0.0, 1.0);
dots = clamp(lum(dots)*lum(dots)*1.0, 0.0, 1.0);
k1 = lum(dots);
dots= k1*vec3(1.0,k1*.8,k1*k1/3.0) *2.0 ;
float cmask = clamp(1.0-16.0*lum(((texture(sampler_blur1, fract(uv3)).xyz * scale1) + bias1)), 0.0, 1.0);
ret += sky * cmask;
ret += fire+dots;

ret += sky*cathed/2.0;
float dis = length(uv1);
float crot = sin((dis+time)*12.0);
vec3 blk = _mod * vec3 (crot,1.0-crot,2.0-dis)*dis;
blk *= (q12*(1.0/rad2+q15*mask2)+q13*(1.0/rad3+q15*mask3))/2.0 ;
blk += q22/rad1*roam_cos.xy-mask1/4.0 ;
ret += blk;






}
